                cout << -1 << "\n";
                return 0;
            }
        }
    }

    // Floyd-Warshall check for consistency
    vector<vector<int64>> d = a;
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (d[i][k] + d[k][j] < d[i][j]) {
                    cout << -1 << "\n";
                    return 0;
                }
            }
        }
    }

    // Find minimal total road length
    int64 total = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            bool needed = true;
            for (int k = 0; k < n; k++) {
                if (k != i && k != j && a[i][j] == a[i][k] + a[k][j]) {
                    needed = false;
                    break;
                }
            }
            if (needed) {
                total += a[i][j];
            }
        }
    }

    cout << total << "\n";
