int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<long long>> A(N, vector<long long>(N));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> A[i][j];
        }
    }

    // Check validity and determine necessary edges.
    long long ans = 0;

    for (int i = 0; i < N; ++i) {
        if (A[i][i] != 0) {
            cout << -1 << '\n';
            return 0;
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (A[i][j] != A[j][i] || A[i][j] <= 0) {
                cout << -1 << '\n';
                return 0;
            }

            bool necessary = true;
            for (int k = 0; k < N; ++k) {
                if (k == i || k == j) continue;

                if (A[i][j] > A[i][k] + A[k][j]) {
                    // Contradiction: given distance is not shortest.
                    cout << -1 << '\n';
                    return 0;
                }
                if (A[i][j] == A[i][k] + A[k][j]) {
                    // Edge (i, j) is redundant.
                    necessary = false;
                }
            }

            if (necessary) ans += A[i][j];
        }
    }

    cout << ans << '\n';
    return 0;
}

