import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[][] A = new long[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                A[i][j] = fs.nextLong();
            }
        }

        // Validate matrix and determine which direct roads are necessary.
        boolean[][] redundant = new boolean[N][N];

        for (int i = 0; i < N; i++) {
            if (A[i][i] != 0) {
                System.out.println(-1);
                return;
            }
            for (int j = 0; j < N; j++) {
                if (i != j && A[i][j] <= 0) {
                    System.out.println(-1);
                    return;
                }
                if (A[i][j] != A[j][i]) {
                    System.out.println(-1);
                    return;
                }
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                for (int k = 0; k < N; k++) {
                    if (k == i || k == j) continue;
                    long via = A[i][k] + A[k][j];
                    if (via < A[i][j]) {
                        System.out.println(-1);
                        return;
                    }
                    if (via == A[i][j]) {
                        redundant[i][j] = true;
                    }
                }
            }
        }

        long ans = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (!redundant[i][j]) ans += A[i][j];
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

